#!/usr/bin/env bash
#
# Keep the Cap'n Proto generated sources in sync with the locally installed
# capnproto.
#
# include/eventProto.capnp.h and src/eventProto.capnp.c++ are *generated* and
# are not tracked in git.  They embed a hard
#
#     #if CAPNP_VERSION != <n>
#     #error "Version mismatch between generated code and library headers."
#
# guard, so they compile only against the exact capnproto version that produced
# them.  This script regenerates them when
#
#   * the schema (eventProto.capnp) is newer than the generated files,
#   * the generated files are missing, or
#   * the capnproto version installed here differs from the version stamped
#     into the generated header,
#
# and is a no-op otherwise.  That keeps `make` working on every machine without
# pinning the repository to one capnproto release.
#
# Usage:
#   ./capnp_sync.sh <schema> [stamp]   sync if needed (used by the Makefile)
#   ./capnp_sync.sh --check <schema>   report status, never modify anything
#   ./capnp_sync.sh --force <schema>   regenerate unconditionally
#
# Environment overrides: CAPNP, CAPNP_HEADER, CAPNP_SOURCE, CAPNP_CFLAGS, CPP.

set -euo pipefail

MODE=sync
case "${1-}" in
--check | --force)
	MODE="${1#--}"
	shift
	;;
esac

SCHEMA=${1:?usage: capnp_sync.sh [--check] <schema> [stamp]}
STAMP=${2:-}

HEADER=${CAPNP_HEADER:-include/eventProto.capnp.h}
SOURCE=${CAPNP_SOURCE:-src/eventProto.capnp.c++}
CXX=${CPP:-g++}
CAPNP=${CAPNP:-capnp}
# Intentionally unquoted: this is a flag list, e.g. "-I/opt/capnp/include".
EXTRA_CPPFLAGS=${CAPNP_CFLAGS:-}

die() {
	echo "capnp_sync: error: $*" >&2
	exit 1
}

# CAPNP_VERSION is MAJOR * 1000000 + MINOR * 1000 + MICRO.
to_capnp_version() {
	awk -F. '{ printf "%d", $1 * 1000000 + $2 * 1000 + $3 }'
}

# Version stamped into the generated header by the capnp compiler that made it.
#
# The emitted guard differs between capnproto releases, so match any of them:
#   0.8.x:  #if CAPNP_VERSION != 8000
#   1.x:    #ifndef CAPNP_VERSION
#           #error "CAPNP_VERSION is not defined, ..."
#           #elif CAPNP_VERSION != 1003000
generated_version() {
	[ -f "$HEADER" ] || return 1
	sed -n 's/^#[[:space:]]*\(if\|elif\)[[:space:]]\+CAPNP_VERSION[[:space:]]*!=[[:space:]]*\([0-9][0-9]*\).*/\2/p' \
		"$HEADER" | head -n 1
}

# Version of the capnp library headers this build will actually compile
# against, queried through the preprocessor so it honours EXTRA_CPPFLAGS and
# any implicit include paths.
library_version() {
	printf '#include <capnp/common.h>\n' |
		$CXX $EXTRA_CPPFLAGS -E -dM -x c++ - 2>/dev/null |
		awk '
			$2 == "CAPNP_VERSION_MAJOR" { major = $3 }
			$2 == "CAPNP_VERSION_MINOR" { minor = $3 }
			$2 == "CAPNP_VERSION_MICRO" { micro = $3 }
			END {
				if (major == "" || minor == "" || micro == "") exit 1
				printf "%d", major * 1000000 + minor * 1000 + micro
			}'
}

tool_version() {
	"$CAPNP" --version 2>/dev/null | sed -n 's/.*version \([0-9][0-9.]*\).*/\1/p' | head -n 1
}

touch_stamp() {
	if [ -n "$STAMP" ]; then
		touch "$STAMP"
	fi
}

[ -f "$SCHEMA" ] || die "schema '$SCHEMA' not found (run make from the repository root)"

LIB="$(library_version || true)"
[ -n "$LIB" ] || die "cannot find the capnp library headers.
       Tried: $CXX $EXTRA_CPPFLAGS with #include <capnp/common.h>
       Install the capnproto C++ library (libcapnp-dev on Debian/Ubuntu)."

GEN="$(generated_version || true)"

# Decide whether the generated code is stale.
STALE=0
REASON=""
if [ "$MODE" = force ]; then
	STALE=1
	REASON="regeneration requested (--force)"
elif [ ! -f "$HEADER" ] || [ ! -f "$SOURCE" ]; then
	STALE=1
	REASON="generated sources are missing"
elif [ -z "$GEN" ]; then
	STALE=1
	REASON="cannot determine the version of the generated code"
elif [ "$GEN" != "$LIB" ]; then
	STALE=1
	REASON="generated by capnproto $GEN, but capnproto $LIB is installed"
elif [ "$SCHEMA" -nt "$HEADER" ] || [ "$SCHEMA" -nt "$SOURCE" ]; then
	STALE=1
	REASON="$SCHEMA is newer than the generated sources"
fi

if [ "$MODE" = check ]; then
	echo "capnproto compiler : $(command -v "$CAPNP" >/dev/null 2>&1 && tool_version || echo 'not found')"
	echo "capnproto library  : $LIB"
	echo "generated code     : ${GEN:-none} ($HEADER)"
	if [ "$STALE" -eq 0 ]; then
		echo "status             : up to date"
	else
		echo "status             : needs regeneration ($REASON)"
	fi
	exit 0
fi

if [ "$STALE" -eq 0 ]; then
	touch_stamp
	exit 0
fi

# Regeneration is required.  Bail out with a helpful message if we cannot do it
# and the existing files are still usable.
if ! command -v "$CAPNP" >/dev/null 2>&1; then
	if [ -f "$HEADER" ] && [ -n "$GEN" ] && [ "$GEN" = "$LIB" ] &&
		[ ! "$SCHEMA" -nt "$HEADER" ] && [ ! "$SCHEMA" -nt "$SOURCE" ]; then
		echo "capnp_sync: warning: '$CAPNP' not found; reusing the existing generated code (capnproto $GEN)." >&2
		touch_stamp
		exit 0
	fi
	die "$REASON
       The capnproto compiler is required to regenerate it, but '$CAPNP' was not
       found in PATH.  Install the package providing 'capnp' and 'capnpc-c++'
       (capnproto on Debian/Ubuntu, capnproto-devel on Fedora/RHEL), then re-run
       make, or run 'make cap' once the compiler is available."
fi

# The compiler and the library must agree, otherwise the generated code can
# never match the headers it will be compiled against.
TOOL_RAW="$(tool_version || true)"
if [ -n "$TOOL_RAW" ]; then
	TOOL_VER="$(printf '%s' "$TOOL_RAW" | to_capnp_version)"
	if [ "$TOOL_VER" != "$LIB" ]; then
		die "capnproto compiler ('$CAPNP' = $TOOL_RAW) and capnproto library headers
       ($LIB) are different versions.  Cap'n Proto requires the compiler and the
       library to match exactly; install a matching pair and re-run make."
	fi
fi

echo "capnp_sync: regenerating Cap'n Proto sources with $(tool_version) ($REASON)"

BASE="$(basename "$SCHEMA" .capnp)"
rm -f "$BASE.capnp.h" "$BASE.capnp.c++"
"$CAPNP" compile -oc++ --src-prefix=. "$SCHEMA"
[ -f "$BASE.capnp.h" ] || die "'$CAPNP compile' did not produce $BASE.capnp.h"
[ -f "$BASE.capnp.c++" ] || die "'$CAPNP compile' did not produce $BASE.capnp.c++"
mv -f "$BASE.capnp.h" "$HEADER"
mv -f "$BASE.capnp.c++" "$SOURCE"

NEW="$(generated_version || true)"
[ "$NEW" = "$LIB" ] || die "regeneration produced code for capnproto '$NEW' but the installed library is '$LIB'."

touch_stamp
